#!/usr/bin/env python3
"""tools/add_dimensions.py YEAR IN.rte OUT.rte DIMS.json MANIFEST.json : add linear dimensions between wall faces to a file whose walls were already regenerated by Revit
(IN = output of `rvt_write.py finish` with touch_walls/openings/rooms: Revit rejects a pure-writer dimension that references an unregenerated writer wall).
DIMS.json: [{"view": <plan view id or name in the manifest 'views'>, "walls": [idA, idB], "at": 13.0}]  (walls = manifest wall ids, parallel + axis aligned; the face on the right-hand side of each wall direction is measured;
'at' = coordinate of the dimension line: y for walls running along y, x for walls along x). Writes OUT.rte and OUT.rte.json (manifest with 'dimensions')."""
import sys,os,json; WL=os.path.expanduser('~/rvt-research/write-lab'); sys.path.insert(0,WL)
import rvtgen,genlib,genlib2,scenes
year,fin,out,dims,man=int(sys.argv[1]),sys.argv[2],sys.argv[3],json.load(open(sys.argv[4])),json.load(open(sys.argv[5]))
g=rvtgen.Gen(fin); tr=scenes.trip(g); DT=genlib2.DimTpl(rvtgen.Gen(os.path.expanduser('~/rvt-research/rosetta/%d_view_dims_fit_var.rte'%year)))
W={w[0]:w for w in man['walls']}; lvz={l[0]:l[2] for l in man.get('levels',[])}; lvz.setdefault(355,0.0)
for d in dims:
    v=[x for x in man['views'] if d['view'] in (x[0],x[1])][0]; axis,xa,xb,ca,cb,ia,ib=genlib2.dim_args(W[d['walls'][0]],W[d['walls'][1]])
    nid=g.nextid; g.nextid+=1; hd,rec,it,row=genlib2.make_dimension(g,DT,nid,v[0],ia,ib,axis,xa,xb,ca,cb,d['at'],lvz.get(v[2],0.0),tr); g.new.append((hd,rec,it,nid)); g.rows.append(row)
    man.setdefault('dimensions',[]).append([nid,'nolist',v[0],ia,ib,axis,xa,xb,d['at'],abs(xb-xa)])
g.commit(out); json.dump(man,open(out+'.json','w')); print('wrote',out,len(dims),'dimensions')
